using System.Windows;using System.Windows.Controls;using SmartErpDesktop.Services;
namespace SmartErpDesktop.Views;public partial class DashboardView:UserControl{private readonly Action<string> navigate;public DashboardView(MockErpService service,Action<string> nav){InitializeComponent();navigate=nav;InvoicesCount.Text=service.Invoices.Count.ToString();CustomersCount.Text=service.Customers.Count.ToString();LowStockCount.Text=service.Products.Count(p=>p.Stock<=p.MinimumStock).ToString();PaymentsCount.Text=service.Payments.Count.ToString();RecentInvoicesGrid.ItemsSource=service.Invoices.Take(5).Select(i=>new{رقم=i.Number,التاريخ=i.Date.ToString("yyyy/MM/dd HH:mm"),العميل=i.CustomerName,النوع=i.Type,الإجمالي=i.Total.ToString("N2"),المتبقي=i.Remaining.ToString("N2"),الحالة=i.Status}).ToList();}private void Sale_Click(object s,RoutedEventArgs e)=>navigate("QuickSale");private void Invoices_Click(object s,RoutedEventArgs e)=>navigate("Invoices");private void Collection_Click(object s,RoutedEventArgs e)=>navigate("Collections");private void Products_Click(object s,RoutedEventArgs e)=>navigate("Products");}
